// SPDX-License-Identifier: Apache-2.0

//! `war frontier` (OW-WAR-0068): the stages that can start now.
//!
//! After mattpocock/skills `to-tickets` and `wayfinder` (MIT): a ticket is
//! unblocked when every ticket blocking it is closed, and the frontier is the
//! open, unblocked, unclaimed set. Here the ticket is a Stage, the blocking
//! edge is its milestone's `depends_on`, "closed" is a milestone whose every
//! obligation an admissible verification established, "claimed" is a
//! `dispatch.compiled` journal event naming the stage, and "done" is a
//! `submission.recorded` event naming it. Nothing here is a status claim: it
//! is derived from the same records `war resolve --dry-run` reads.
//!
//! Three choices, stated: `done` wins over `blocked` (a recorded submission
//! is history, whatever the graph says now); a milestone with no obligations
//! never completes, so everything behind it stays blocked until someone
//! writes the obligation (fail closed, and reported); a stage cited by more
//! than one milestone is one row, blocked if any of them waits.
//!
//! A second blocking edge (OW-WAR-0132): a blocking question on the stage that
//! no human has answered. The stage is `blocked` and its `waiting_on` names the
//! question beside any milestone; every other stage is untouched, and an
//! answered question blocks nothing. When the authority register holds no
//! actor who is not an agent, nobody can answer, and each such stage also
//! carries UNKNOWN `question.no-responder` naming `roles.toml`: neither
//! waiting normally nor answered (Law 15).

use std::collections::{BTreeMap, BTreeSet};

use serde::Serialize;

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum StageState {
    /// Unblocked, undispatched: on the frontier.
    Open,
    /// Dispatched (a `dispatch.compiled` event), no submission yet.
    Claimed,
    /// A submission is recorded for it.
    Done,
    /// Its milestone waits on another milestone that is not complete, or a
    /// blocking question on it is unanswered.
    Blocked,
}

#[derive(Debug, Clone, Serialize)]
pub struct Row {
    pub warrant: String,
    pub stage: String,
    pub title: String,
    pub milestone: String,
    pub executor_kind: String,
    pub state: StageState,
    /// Milestones this one's milestone waits on and that are not complete,
    /// then the blocking questions on it that are unanswered (`Q-nnn`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub waiting_on: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Frontier {
    pub schema: String,
    pub rows: Vec<Row>,
    pub open: usize,
    pub claimed: usize,
    pub done: usize,
    pub blocked: usize,
}

pub const SCHEMA: &str = "oh.war/frontier/v1";

fn stage_events(dir: &camino::Utf8Path) -> Result<(BTreeSet<String>, BTreeSet<String>), RepoError> {
    let mut claimed = BTreeSet::new();
    let mut done = BTreeSet::new();
    let path = dir.join(crate::journal_cmd::FILE);
    match std::fs::symlink_metadata(&path) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok((claimed, done)),
        Err(source) => {
            return Err(RepoError::Io {
                context: format!("could not inspect {path}"),
                source,
            });
        }
        Ok(_) => {}
    }
    let metadata = std::fs::metadata(&path).map_err(|source| RepoError::Io {
        context: format!("could not inspect {path}"),
        source,
    })?;
    if !metadata.is_file() {
        return Err(RepoError::Message(format!(
            "{path}: journal must be a regular file"
        )));
    }
    // The legacy loader treats non-files as absent. Admission must distinguish
    // missing history from damaged containers and dangling links.
    let text = std::fs::read_to_string(&path).map_err(|source| RepoError::Io {
        context: format!("could not read {path}"),
        source,
    })?;
    let j =
        crate::journal_cmd::parse(&text).map_err(|e| RepoError::Message(format!("{path}: {e}")))?;
    for e in &j.events {
        if !matches!(
            e.event_type.as_str(),
            "dispatch.compiled" | "submission.recorded"
        ) {
            continue;
        }
        let payload: serde_json::Value = serde_json::from_str(&e.payload).map_err(|_| {
            RepoError::Message(format!(
                "{path}: {} event {} has invalid JSON payload",
                e.event_type, e.id
            ))
        })?;
        let stage = payload
            .get("stage")
            .and_then(serde_json::Value::as_str)
            .filter(|stage| !stage.trim().is_empty())
            .ok_or_else(|| {
                RepoError::Message(format!(
                    "{path}: {} event {} requires a nonempty string stage",
                    e.event_type, e.id
                ))
            })?;
        if e.event_type == "dispatch.compiled" {
            claimed.insert(stage.to_owned());
        } else {
            done.insert(stage.to_owned());
        }
    }
    Ok((claimed, done))
}

/// The frontier of one Warrant, or of every unresolved Warrant.
pub fn run(repo: &Repository, alias: Option<&str>) -> Result<(Report, Frontier), RepoError> {
    let mut report = Report::default();
    let dirs = match alias {
        Some(a) => vec![repo.warrant_dir(a)?],
        None => repo.warrant_dirs()?,
    };
    let mut rows = Vec::new();
    // Read once, and only if a blocking question needs it.
    let mut responder: Option<Result<bool, String>> = None;
    for dir in dirs {
        let one = repo.load_warrant(&dir)?;
        let alias = dir.file_name().unwrap_or_default().to_owned();
        if repo.load_resolution(&dir)?.is_some() {
            continue;
        }
        let basis = one.basis.as_ref().ok_or_else(|| {
            RepoError::Message(format!("{alias}: no readable workspace basis for frontier"))
        })?;
        let Some(text) = basis
            .atoms
            .iter()
            .find(|a| a.role == "milestones")
            .and_then(|a| String::from_utf8(a.bytes.clone()).ok())
        else {
            if one
                .validated
                .as_ref()
                .is_some_and(|v| !v.raw.atoms.iter().any(|a| a.role == "milestones"))
            {
                continue;
            }
            return Err(RepoError::Message(format!(
                "{alias}: no readable milestones atom for frontier"
            )));
        };
        let graph = openwarrant_core::milestones::parse(&text)
            .map_err(|e| RepoError::Message(format!("{alias}: invalid milestones: {e}")))?;
        let established: BTreeSet<String> = crate::resolve::assess(repo, &one)?
            .established
            .into_iter()
            .collect();
        let complete: BTreeMap<&str, bool> = graph
            .milestones
            .iter()
            .map(|m| {
                (
                    m.id.as_str(),
                    !m.obligation_refs.is_empty()
                        && m.obligation_refs.iter().all(|o| established.contains(o)),
                )
            })
            .collect();
        for m in graph
            .milestones
            .iter()
            .filter(|m| m.obligation_refs.is_empty())
        {
            if graph
                .milestones
                .iter()
                .any(|o| o.depends_on.contains(&m.id))
            {
                report.push(Diagnostic::warn(
                    "frontier.milestone-without-obligations",
                    repo.relative(&dir.join("atoms/45-milestones.yaml")),
                    format!(
                        "{alias}: {} has no obligation_refs, so it never completes and every milestone depending on it stays blocked",
                        m.id
                    ),
                ));
            }
        }
        let (claimed, done) = stage_events(&dir)?;
        let asked = open_blocking(repo, &alias, &mut report);
        // One row per stage: its milestones' waits are unioned.
        let mut per_stage: BTreeMap<String, (Vec<String>, BTreeSet<String>)> = BTreeMap::new();
        for m in &graph.milestones {
            let waiting: Vec<String> = m
                .depends_on
                .iter()
                .filter(|d| !complete.get(d.as_str()).copied().unwrap_or(false))
                .cloned()
                .collect();
            for sid in &m.stage_refs {
                let entry = per_stage.entry(sid.clone()).or_default();
                entry.0.push(m.id.clone());
                entry.1.extend(waiting.iter().cloned());
            }
        }
        for (sid, (milestones, waiting)) in per_stage {
            let Some(stage) = graph.stages.iter().find(|s| s.id == sid) else {
                continue;
            };
            let questions = asked.get(&sid).cloned().unwrap_or_default();
            let mut waiting: Vec<String> = waiting.into_iter().collect();
            waiting.extend(questions.iter().cloned());
            let state = if done.contains(&sid) {
                StageState::Done
            } else if !waiting.is_empty() {
                StageState::Blocked
            } else if claimed.contains(&sid) {
                StageState::Claimed
            } else {
                StageState::Open
            };
            if state == StageState::Blocked && !questions.is_empty() {
                let answerable = responder.get_or_insert_with(|| someone_can_answer(repo));
                if let Some(why) = no_responder(answerable) {
                    report.push(Diagnostic::unknown(
                        "question.no-responder",
                        "docs/authority/roles.toml".to_owned(),
                        format!(
                            "{alias}/{sid} waits on {} and {why}, so nobody can answer:                              `war answer` refuses an agent by kind (§27.2). The stage stays                              blocked; it is not waiting normally and it is not answered. A human                              added to docs/authority/roles.toml can answer",
                            questions.join(", ")
                        ),
                    ));
                }
            }
            rows.push(Row {
                warrant: alias.clone(),
                stage: sid.clone(),
                title: stage.title.clone().unwrap_or_default(),
                milestone: milestones.join("+"),
                executor_kind: stage.executor_kind.to_string(),
                state,
                waiting_on: if state == StageState::Blocked {
                    waiting
                } else {
                    vec![]
                },
            });
        }
    }
    rows.sort_by(|a, b| (&a.warrant, &a.stage).cmp(&(&b.warrant, &b.stage)));
    let count = |s: StageState| rows.iter().filter(|r| r.state == s).count();
    let f = Frontier {
        schema: SCHEMA.to_owned(),
        open: count(StageState::Open),
        claimed: count(StageState::Claimed),
        done: count(StageState::Done),
        blocked: count(StageState::Blocked),
        rows,
    };
    report.note(format!(
        "{} open, {} claimed, {} done, {} blocked across {} stage(s)",
        f.open,
        f.claimed,
        f.done,
        f.blocked,
        f.rows.len()
    ));
    Ok((report, f))
}

/// The unanswered blocking questions of one Warrant, by stage. A question
/// store that cannot be read is reported, not taken to hold nothing.
fn open_blocking(
    repo: &Repository,
    alias: &str,
    report: &mut Report,
) -> BTreeMap<String, Vec<String>> {
    let (questions, unreadable) = crate::questions::load_tolerant(repo, alias);
    for path in unreadable {
        report.push(Diagnostic::unknown(
            "frontier.question-unreadable",
            path,
            format!(
                "{alias}: a question record cannot be read, so whether it blocks a stage cannot                  be established; the rows below count only the readable ones"
            ),
        ));
    }
    let mut by_stage: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for q in questions.into_iter().filter(|q| q.blocking && q.is_open()) {
        by_stage.entry(q.stage).or_default().push(q.id);
    }
    by_stage
}

/// Whether the register names an actor `war answer` would accept: any
/// assignment whose kind is not `agent` (A-002). `Err` when the register
/// cannot be read at all.
fn someone_can_answer(repo: &Repository) -> Result<bool, String> {
    repo.load_authority_register()
        .map(|r| {
            r.assignments
                .iter()
                .any(|a| a.actor_kind != openwarrant_core::authority::ActorKind::Agent)
        })
        .map_err(|e| e.to_string())
}

/// The clause of the no-responder finding, or `None` when someone can answer.
fn no_responder(answerable: &Result<bool, String>) -> Option<String> {
    match answerable {
        Ok(true) => None,
        Ok(false) => Some(
            "docs/authority/roles.toml holds no actor whose actor_kind is not `agent`".to_owned(),
        ),
        Err(e) => Some(format!("docs/authority/roles.toml cannot be read ({e})")),
    }
}

#[must_use]
pub fn render(f: &Frontier) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "frontier: {} open · {} claimed · {} done · {} blocked\n\n",
        f.open, f.claimed, f.done, f.blocked
    ));
    for r in &f.rows {
        let state = match r.state {
            StageState::Open => "OPEN   ",
            StageState::Claimed => "CLAIMED",
            StageState::Done => "done   ",
            StageState::Blocked => "blocked",
        };
        out.push_str(&format!(
            "  {state}  {:<12} {:<10} {:<4} {:<8} {}{}\n",
            r.warrant,
            r.stage,
            r.milestone,
            r.executor_kind,
            r.title,
            if r.waiting_on.is_empty() {
                String::new()
            } else {
                format!("  (waits on {})", r.waiting_on.join(", "))
            }
        ));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_four_states_are_distinct_words() {
        for s in [
            StageState::Open,
            StageState::Claimed,
            StageState::Done,
            StageState::Blocked,
        ] {
            let j = serde_json::to_string(&s).unwrap();
            assert!(["\"open\"", "\"claimed\"", "\"done\"", "\"blocked\""].contains(&j.as_str()));
        }
    }
}

// SPDX-License-Identifier: Apache-2.0
//! Stage-relevant context selection (slice C1; SAS §47.2 "select only
//! stage-relevant context", §33 context manifest).
//!
//! Before this, a Dispatch's context was required-vs-optional: every required
//! atom included whole, every optional one omitted, whatever the stage. A
//! stage may now declare what it needs — whole atoms, named sections of an
//! atom, repository artifacts, external references — and the selection is:
//!
//!   included = required atoms ∪ declared atoms ∪ declared sections
//!            ∪ declared artifacts ∪ declared external references
//!   omitted  = everything else, each with a TRUE reason.
//!
//! A declared section that does not exist is refused by name, with the
//! headings that do; a declared atom or artifact that does not exist is
//! refused. Sorted, so the manifest is deterministic.

use camino::Utf8Path;
use openwarrant_compiler::CompilationBasis;
use openwarrant_core::context::{
    ContextItem, ContextRole, Holder, Omission, Precedence, TrustClass,
};
use openwarrant_core::milestones::Stage;
use sha2::Digest;

use crate::repo::Repository;

/// One refusal, by rule, for `war check`-style reporting.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Refusal {
    pub rule: &'static str,
    pub message: String,
}

pub struct Selection {
    pub included: Vec<ContextItem>,
    pub omitted: Vec<Omission>,
    /// The bytes each included item actually carries: whole atoms, section
    /// bodies, artifact files; an external ref carries none. Sorted by id.
    pub bytes: Vec<(String, u64)>,
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut h = sha2::Sha256::new();
    h.update(bytes);
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

fn role_for(atom_role: &str) -> ContextRole {
    match atom_role {
        "basis" => ContextRole::Governing,
        "intent" | "work_order" | "milestones" | "assurance" => ContextRole::Normative,
        _ => ContextRole::Informative,
    }
}

/// Select the context for `stage` out of `basis`.
pub fn select(
    repo: &Repository,
    warrant_dir: &Utf8Path,
    basis: &CompilationBasis,
    stage: &Stage,
    commit: Option<&str>,
) -> Result<Selection, Vec<Refusal>> {
    let mut refusals = Vec::new();
    let mut included: Vec<ContextItem> = Vec::new();
    let mut omitted: Vec<Omission> = Vec::new();
    let mut bytes: Vec<(String, u64)> = Vec::new();
    let holder = |path: String| Holder {
        kind: "git".to_owned(),
        repository: repo.config.project.name.clone(),
        commit_sha: commit.unwrap_or_default().to_owned(),
        path,
    };
    let atom_by_name = |name: &str| {
        basis
            .atoms
            .iter()
            .find(|a| a.source == name || a.source.rsplit('/').next() == Some(name))
    };

    // Whole atoms: every required one, plus the declared ones.
    let declared_atoms: Vec<&str> = stage.context_atoms.iter().map(String::as_str).collect();
    for name in &declared_atoms {
        if atom_by_name(name).is_none() {
            refusals.push(Refusal {
                rule: "dispatch.unknown-atom",
                message: format!(
                    "{}: context_atoms names {name:?}, which is not an atom of this Warrant; declared: {}",
                    stage.id,
                    basis.atoms.iter().map(|a| a.source.as_str()).collect::<Vec<_>>().join(", ")
                ),
            });
        }
    }
    // Sections: `<atom>#<heading>`.
    let mut section_items: Vec<(String, String, String)> = Vec::new(); // (atom source, heading, body)
    for sel in &stage.context_sections {
        let Some((atom_name, heading)) = sel.split_once('#') else {
            refusals.push(Refusal {
                rule: "dispatch.section-missing",
                message: format!(
                    "{}: context_sections entry {sel:?}: not of the form `<atom>#<heading>`",
                    stage.id
                ),
            });
            continue;
        };
        let Some(atom) = atom_by_name(atom_name) else {
            refusals.push(Refusal {
                rule: "dispatch.unknown-atom",
                message: format!("{}: context_sections names atom {atom_name:?}, which this Warrant does not have", stage.id),
            });
            continue;
        };
        let text = String::from_utf8_lossy(&atom.bytes);
        match openwarrant_core::sections::find(&text, heading) {
            Some(body) => {
                section_items.push((atom.source.clone(), heading.trim().to_owned(), body))
            }
            None => {
                let known: Vec<String> = openwarrant_core::sections::headings(&text)
                    .into_iter()
                    .map(|(_, t)| t)
                    .collect();
                refusals.push(Refusal {
                    rule: "dispatch.section-missing",
                    message: format!(
                        "{}: {atom_name} has no section {heading:?}; its headings are: {}",
                        stage.id,
                        known.join(" | ")
                    ),
                });
            }
        }
    }
    // Artifacts: repository paths that exist.
    let mut artifact_items = Vec::new();
    for path in &stage.context_artifacts {
        let full = repo.root.join(path);
        match std::fs::read(&full) {
            Ok(content) => {
                artifact_items.push((path.clone(), sha256_hex(&content), content.len() as u64))
            }
            Err(e) => refusals.push(Refusal {
                rule: "dispatch.artifact-missing",
                message: format!("{}: context_artifacts names {path:?}: {e}", stage.id),
            }),
        }
    }
    if !refusals.is_empty() {
        return Err(refusals);
    }

    for atom in &basis.atoms {
        let declared = declared_atoms
            .iter()
            .any(|n| *n == atom.source || atom.source.rsplit('/').next() == Some(n));
        let sectioned = section_items.iter().any(|(s, _, _)| *s == atom.source);
        if atom.required || declared {
            bytes.push((atom.source.clone(), atom.bytes.len() as u64));
            included.push(ContextItem {
                id: atom.source.clone(),
                role: role_for(&atom.role),
                required: atom.required,
                holder: holder(repo.relative(&warrant_dir.join(&atom.source))),
                content_digest: format!("sha256:{}", sha256_hex(&atom.bytes)),
                selector_sections: vec![],
                classification: "internal".to_owned(),
                trust: TrustClass::AuthoritativeInternal,
                taints: vec![],
                precedence: Some(Precedence::AuthorizedWarContract),
            });
        } else if !sectioned {
            omitted.push(Omission {
                id: atom.source.clone(),
                reason: format!(
                    "optional atom of role {:?}; {} declares neither it nor a section of it (§47.2 \"select only stage-relevant context\")",
                    atom.role, stage.id
                ),
                required: false,
            });
        }
    }
    for (source, heading, body) in &section_items {
        // A section of an atom that is included whole (every required atom
        // is, §47.2 "preserve every required normative source") narrows that
        // item: the section is recorded on it as a selector, and the packet's
        // context digest moves with the selection.
        if let Some(item) = included.iter_mut().find(|i| i.id == *source) {
            item.selector_sections.push(heading.clone());
            item.selector_sections.sort();
            item.selector_sections.dedup();
            continue;
        }
        bytes.push((format!("{source}#{heading}"), body.len() as u64));
        let atom = atom_by_name(source).expect("resolved above");
        included.push(ContextItem {
            id: format!("{source}#{heading}"),
            role: role_for(&atom.role),
            required: false,
            holder: holder(repo.relative(&warrant_dir.join(source))),
            content_digest: format!("sha256:{}", sha256_hex(body.as_bytes())),
            selector_sections: vec![heading.clone()],
            classification: "internal".to_owned(),
            trust: TrustClass::AuthoritativeInternal,
            taints: vec![],
            precedence: Some(Precedence::AuthorizedWarContract),
        });
    }
    for (path, digest, len) in artifact_items {
        bytes.push((path.clone(), len));
        included.push(ContextItem {
            id: path.clone(),
            role: ContextRole::Input,
            required: false,
            holder: holder(path),
            content_digest: format!("sha256:{digest}"),
            selector_sections: vec![],
            classification: "internal".to_owned(),
            trust: TrustClass::InternalUnverified,
            taints: vec![],
            precedence: Some(Precedence::InformativeSource),
        });
    }
    // The program's glossary (OW-WAR-0068, after mattpocock/skills
    // domain-modeling): a term defined once at the root costs one word in
    // every Dispatch, so the selector carries it whenever it exists.
    let glossary = repo.root.join("CONTEXT.md");
    if let Ok(body) = std::fs::read(&glossary) {
        bytes.push(("CONTEXT.md".to_owned(), body.len() as u64));
        included.push(ContextItem {
            id: "CONTEXT.md".to_owned(),
            role: ContextRole::Informative,
            required: false,
            holder: holder("CONTEXT.md".to_owned()),
            content_digest: format!("sha256:{}", sha256_hex(&body)),
            selector_sections: vec![],
            classification: "internal".to_owned(),
            trust: TrustClass::AuthoritativeInternal,
            taints: vec![],
            precedence: Some(Precedence::InformativeSource),
        });
    }
    for uri in &stage.context_external {
        included.push(ContextItem {
            id: uri.clone(),
            role: ContextRole::Informative,
            required: false,
            holder: Holder {
                kind: "external".to_owned(),
                repository: String::new(),
                commit_sha: String::new(),
                path: uri.clone(),
            },
            // Recorded, never fetched: no digest can honestly be claimed.
            content_digest: String::new(),
            selector_sections: vec![],
            classification: "internal".to_owned(),
            trust: TrustClass::ExternalUntrusted,
            taints: vec!["unfetched".to_owned()],
            precedence: Some(Precedence::InformativeSource),
        });
    }
    included.sort_by(|a, b| a.id.cmp(&b.id));
    omitted.sort_by(|a, b| a.id.cmp(&b.id));
    bytes.sort();
    Ok(Selection {
        included,
        omitted,
        bytes,
    })
}
